import * as THREE from './vendor/three.module.min.js';

// CPU fallback keeps the same scene, perspective camera, raycasting and controls.
// This makes the editor usable on office PCs with WebGL disabled by policy.
export class SoftwareRenderer {
 constructor(){this.domElement=document.createElement('canvas');this.ctx=this.domElement.getContext('2d');this.pixelRatio=1;this.width=1;this.height=1;this.shadowMap={};this.info={render:{calls:0,triangles:0}};this.isSoftwareRenderer=true;this.tmp=new THREE.Vector3();}
 setPixelRatio(v){this.pixelRatio=Math.min(v,1.5);}
 setSize(w,h,style=false){this.width=w;this.height=h;this.domElement.width=Math.max(1,Math.round(w*this.pixelRatio));this.domElement.height=Math.max(1,Math.round(h*this.pixelRatio));if(style){this.domElement.style.width=w+'px';this.domElement.style.height=h+'px';}}
 project(p){const v=p.clone().applyMatrix4(this.pv);return{x:(v.x+1)*this.width/2,y:(1-v.y)*this.height/2,z:v.z};}
 path(points){const c=this.ctx;c.beginPath();points.forEach((p,n)=>n?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.closePath();}
 render(scene,camera){const c=this.ctx,W=this.width,H=this.height;camera.updateMatrixWorld();scene.updateMatrixWorld();this.pv=new THREE.Matrix4().multiplyMatrices(camera.projectionMatrix,camera.matrixWorldInverse);c.setTransform(this.pixelRatio,0,0,this.pixelRatio,0,0);c.globalAlpha=1;c.fillStyle='#f4f5f7';c.fillRect(0,0,W,H);const faces=[],shadowCasters=[],floorMeshes=[];const light=new THREE.Vector3(-.25,.85,.5).normalize(),camPos=camera.position,normalMatrix=new THREE.Matrix3();let count=0;
 const addFace=(vertices,normal,obj,material,panel)=>{if(obj.userData.platform&&normal.y>.5)return;const world=vertices.map(p=>p.clone().applyMatrix4(obj.matrixWorld)),center=world.reduce((a,p)=>a.add(p),new THREE.Vector3()).multiplyScalar(1/world.length);const n=normal.clone().applyMatrix3(normalMatrix).normalize();if(n.dot(camPos.clone().sub(center))<-.001&&material.side!==THREE.DoubleSide)return;const pp=world.map(p=>this.project(p));if(pp.every(p=>p.z>1||p.z< -1)||pp.every(p=>p.x< -150)||pp.every(p=>p.x>W+150)||pp.every(p=>p.y< -150)||pp.every(p=>p.y>H+150))return;let col=material.color?.clone()||new THREE.Color('#b9c6bd');if(material.map&&obj.geometry.type==='BoxGeometry')col=new THREE.Color('#ceae7d');const amount=.77+Math.max(0,n.dot(light))*.24+Math.max(0,n.y)*.045;col.multiplyScalar(amount);faces.push({points:pp,color:'#'+col.getHexString(THREE.SRGBColorSpace),alpha:material.opacity??1,depth:center.distanceToSquared(camPos),normal:n,center,panel});count++;};
 const walk=(obj,panel=false)=>{if(!obj.visible)return;panel=panel||(obj.userData.wallPanel===true?obj:null);if(obj.isMesh&&obj.geometry&&obj.material){const geo=obj.geometry,mat=Array.isArray(obj.material)?obj.material[0]:obj.material;normalMatrix.getNormalMatrix(obj.matrixWorld);if(obj.userData.floor){floorMeshes.push(obj);}else if(geo.type==='BoxGeometry'){
  const p=geo.parameters,x=p.width/2,y=p.height/2,z=p.depth/2,vs=[[-x,-y,-z],[x,-y,-z],[x,y,-z],[-x,y,-z],[-x,-y,z],[x,-y,z],[x,y,z],[-x,y,z]].map(v=>new THREE.Vector3(...v));for(const [indices,n]of [[[0,3,2,1],[0,0,-1]],[[4,5,6,7],[0,0,1]],[[0,4,7,3],[-1,0,0]],[[1,2,6,5],[1,0,0]],[[3,7,6,2],[0,1,0]],[[0,1,5,4],[0,-1,0]]])addFace(indices.map(i=>vs[i]),new THREE.Vector3(...n),obj,mat,panel);
 }else{const pos=geo.attributes.position,norm=geo.attributes.normal,idx=geo.index;for(let j=0;j<(idx?idx.count:pos.count);j+=3){const ids=[0,1,2].map(k=>idx?idx.getX(j+k):j+k),vertices=ids.map(i=>new THREE.Vector3().fromBufferAttribute(pos,i)),n=norm?new THREE.Vector3().fromBufferAttribute(norm,ids[0]):new THREE.Vector3().subVectors(vertices[1],vertices[0]).cross(new THREE.Vector3().subVectors(vertices[2],vertices[0])).normalize();addFace(vertices,n,obj,mat,panel);}}
 if(obj.castShadow&&geo.type==='BoxGeometry'&&obj.matrixWorld.elements[13]>.12&&mat.opacity>.5)shadowCasters.push(obj);
 }for(const child of obj.children)walk(child,panel);};walk(scene);
 for(const floor of floorMeshes){const r=floor.userData.room,w=r.w,d=r.d,y=-.043,project=(x,z)=>this.project(new THREE.Vector3(x,y,z));const pp=[project(0,0),project(w,0),project(w,d),project(0,d)];this.path(pp);c.fillStyle='#e1ded5';c.fill();if(r.grid){c.save();this.path(pp);c.clip();c.strokeStyle='#bdc1b75c';c.lineWidth=.7;for(let x=0;x<=w+.001;x+=.45){const a=project(x,0),b=project(x,d);c.beginPath();c.moveTo(a.x,a.y);c.lineTo(b.x,b.y);c.stroke();}for(let z=0;z<=d+.001;z+=.45){const a=project(0,z),b=project(w,z);c.beginPath();c.moveTo(a.x,a.y);c.lineTo(b.x,b.y);c.stroke();}c.restore();}
 // Small contact shadows ground furniture without obscuring the 45cm tile grid.
 c.save();this.path(pp);c.clip();for(const obj of shadowCasters){const p=obj.geometry.parameters;if(p.width*p.depth<.035||p.height<.025)continue;const points=[];for(const [x,z]of[[-1,-1],[1,-1],[1,1],[-1,1]]){const v=new THREE.Vector3(x*p.width/2,0,z*p.depth/2).applyMatrix4(obj.matrixWorld);points.push(project(v.x+.08,v.z+.08));}this.path(points);c.shadowColor='#304a3422';c.shadowBlur=7;c.fillStyle='#43583e0c';c.fill();}c.restore();}
 // Parallel wall panels need plane ordering: their center heights differ, so
 // center distance alone can incorrectly paint board edges on a lowered screen.
 faces.sort((a,b)=>b.depth-a.depth);
 const panelPlanes=[];for(let i=0;i<faces.length;i++){const f=faces[i];if(!f.panel)continue;const normal=new THREE.Vector3(0,0,1).transformDirection(f.panel.matrixWorld);let plane=panelPlanes.find(p=>Math.abs(p.normal.dot(normal))>.9999);if(!plane){plane={normal,slots:[],layers:new Map()};panelPlanes.push(plane);}plane.slots.push(i);if(!plane.layers.has(f.panel))plane.layers.set(f.panel,{position:new THREE.Vector3().setFromMatrixPosition(f.panel.matrixWorld),faces:[]});plane.layers.get(f.panel).faces.push(f);}
 for(const plane of panelPlanes){const layers=[...plane.layers.values()],side=Math.sign(plane.normal.dot(camPos.clone().sub(layers[0].position)))||1;layers.sort((a,b)=>side*plane.normal.dot(a.position.clone().sub(b.position)));const ordered=layers.flatMap(layer=>layer.faces);plane.slots.forEach((slot,i)=>faces[slot]=ordered[i]);}
  for(const f of faces){c.globalAlpha=f.alpha;this.path(f.points);c.fillStyle=f.color;c.fill();if(f.alpha>.95){c.lineWidth=.3;c.strokeStyle=f.color;c.stroke();}}c.globalAlpha=1;
 // Selection outlines are actual projected geometry, identical to WebGL outlines.
 scene.traverse(obj=>{if(!obj.visible||!obj.isLine||!obj.geometry)return;for(let parent=obj.parent;parent;parent=parent.parent)if(!parent.visible)return;const p=obj.geometry.attributes.position,pts=[];for(let i=0;i<p.count;i++)pts.push(this.project(new THREE.Vector3().fromBufferAttribute(p,i).applyMatrix4(obj.matrixWorld)));if(!pts.length)return;c.beginPath();pts.forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));if(obj.isLineLoop)c.closePath();c.strokeStyle='#'+obj.material.color.getHexString();c.lineWidth=1.6;c.stroke();});this.info.render.calls=faces.length;this.info.render.triangles=count*2;
 }
}
